#!/usr/bin/env sh
# Check the English documents against the ASD-STE100 limits.
# The linter is vendored. See scripts/vendor/README.md.
set -eu

# docs/arch/README.md is generated by likec4 export markdown. The linter skips it.
for document in README.md AGENTS.md docs/architecture.md docs/configuration.md \
  docs/glossary.md docs/prior-art.md docs/prompts.md docs/questions.md \
  docs/adr/*.md docs/features/README.md; do
  set -- "$@" "$document"
done
exec python3 scripts/vendor/ste-lint.py "$@"
